import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

const percent = (fallback = 0) => z.coerce.number().catch(fallback).transform(v => Number.isFinite(v) ? _.clamp(v, 0, 100) : fallback).prefault(fallback);
const signedPercent = (fallback = 0) => z.coerce.number().catch(fallback).transform(v => Number.isFinite(v) ? _.clamp(v, -100, 100) : fallback).prefault(fallback);
const nonNegative = (fallback = 0) => z.coerce.number().catch(fallback).transform(v => Number.isFinite(v) ? Math.max(0, v) : fallback).prefault(fallback);
const text = (fallback = '未知') => z.coerce.string().catch(fallback).prefault(fallback);
const limitedRecord = (item, limit) => z.record(z.string(), item).catch({}).prefault({}).transform(data => _(data).entries().takeRight(limit).fromPairs().value());
const stateObject = z.record(z.string(), z.unknown()).catch({}).prefault({});
const combatMetadata = z.object({ 修正: signedPercent(0), 基础伤害: nonNegative(0), 距离: text('无'), 消耗: text('无'), 冷却: text('无'), 破阶标签: z.array(z.string()).catch([]).prefault([]), 限制: text('无') }).passthrough().catch({}).prefault({});

const abilityItem = z.object({ 状态: text('未知'), 可用性: z.enum(['可用', '受限', '冷却中', '不可用', '已失去', '未知']).catch('未知').prefault('未知'), 消耗或冷却: text('无'), 描述: text(''), 战斗元数据: combatMetadata.optional() }).passthrough();
const abilities = z.object({ 加护: z.record(z.string(), abilityItem).catch({}).prefault({}), 权能: z.record(z.string(), abilityItem).catch({}).prefault({}), 魔法: z.record(z.string(), abilityItem).catch({}).prefault({}), 精灵术: z.record(z.string(), abilityItem).catch({}).prefault({}), 种族能力: z.record(z.string(), abilityItem).catch({}).prefault({}), 武技: z.record(z.string(), abilityItem).catch({}).prefault({}), 一般技能: z.record(z.string(), abilityItem).catch({}).prefault({}) }).passthrough().catch({}).prefault({});
const injury = z.object({ 部位: text(), 程度: z.enum(['轻微', '轻度', '中度', '重度', '致命', '未知']).catch('未知').prefault('未知'), 描述: text('') }).passthrough();
const abnormal = z.object({ 类型: text(), 剩余表现: text(), 描述: text('') }).passthrough();
const alive = z.enum(['存活', '濒死', '昏迷', '失踪', '生死未卜', '死亡']).catch('存活').prefault('存活');
const combatTier = z.object({ 阶数: text(), 位阶: z.enum(['上位', '下位', '未定', '未知']).catch('未知').prefault('未知'), 可战状态: z.enum(['可战', '受限', '无法战斗', '未知']).catch('未知').prefault('未知'), 生效条件: text('无') }).passthrough().catch({}).prefault({});
const sharedCombatFields = { 战斗状态: text('未知'), 战力等阶: combatTier, 生命: percent(100), 伤势: z.record(z.string(), injury).catch({}).prefault({}), 能力引用: z.array(z.string()).catch([]).prefault([]), 可战状态: z.enum(['可战', '受限', '无法战斗', '未知']).catch('未知').prefault('未知'), 体力: percent(100), 魔力: percent(100), 精神稳定: percent(100), 当前目标: text('无'), 当前行动: text('无') };
const protagonist = z.object({ 主角锁定: z.coerce.boolean().catch(false).prefault(false), 姓名: text(), 角色类型: z.enum(['原作人物', '原创角色', '未知']).catch('未知').prefault('未知'), 性别: text(), 年龄阶段: text(), 种族: text(), 身份: text(), 阵营: text(), 容貌: text(), 衣着: text(), 生存状态: alive, 生命: percent(100), 体力: percent(100), 魔力: percent(100), 精神稳定: percent(100), 门状态: text(), 门负荷: percent(0), 魔女余香: percent(0), 伤势: z.record(z.string(), injury).catch({}).prefault({}), 异常状态: z.record(z.string(), abnormal).catch({}).prefault({}), 当前形态: text('常态'), 能力: abilities, ...sharedCombatFields }).passthrough().catch({}).prefault({});
const person = z.object({ 身份: text(), 阵营: text(), 关系阶段: text('陌生'), 立场: text('中立'), 好感: signedPercent(0), 信任: percent(0), 生存状态: alive, 生命: percent(100), 魔力: percent(100), 伤势: z.record(z.string(), injury).catch({}).prefault({}), 异常状态: z.record(z.string(), abnormal).catch({}).prefault({}), 当前地点: text(), 当前形态: text('常态'), ...sharedCombatFields }).passthrough();
const partner = z.object({ 关系阶段: text('已确认'), 亲密度: percent(0), 立场: text('友方'), 生存状态: alive, 当前地点: text(), ...sharedCombatFields }).passthrough();
const contractedPartner = z.object({ 契约状态: text('有效'), 关系阶段: text('已契约'), 信任: percent(0), 立场: text('友方'), 生存状态: alive, 当前地点: text(), ...sharedCombatFields }).passthrough();
const deathRecord = z.object({ 重启编号: nonNegative(0), 死亡时规范日期与时段: text(), 死亡时地点: text(), 直接原因: text(), 死亡经过与最后行动: text(), 在场或相关人物: z.array(z.string()).catch([]).prefault([]), 触发前轮回分支: text('B00'), 本轮遗留情报: z.array(z.string()).catch([]).prefault([]).transform(data => data.slice(-5)) }).passthrough();
const eventItem = z.object({ 标题: text('未命名事件'), 类型: text(), 阶段: z.enum(['起', '承', '转', '合']).catch('起').prefault('起'), 状态: text('进行中'), 地点: text(), 参与者: z.array(z.string()).catch([]).prefault([]), 目标: text('无'), 描述: text('') }).passthrough();
const checkSummary = z.object({ 检定类型: text(''), 骰面: z.coerce.number().catch(0).transform(v => Number.isFinite(v) ? _.clamp(v, 0, 20) : 0).prefault(0), 目标DC: nonNegative(0), 修正: signedPercent(0), 总值: z.coerce.number().catch(0).transform(v => Number.isFinite(v) ? v : 0).prefault(0), 结果等级: text(''), 目标: text(''), 时间: text('') }).strip().catch({ 检定类型: '', 骰面: 0, 目标DC: 0, 修正: 0, 总值: 0, 结果等级: '', 目标: '', 时间: '' }).prefault({ 检定类型: '', 骰面: 0, 目标DC: 0, 修正: 0, 总值: 0, 结果等级: '', 目标: '', 时间: '' });
const stableId = z.string().catch('').transform(value => value.trim()).prefault('');
const battleId = stableId;
const emptyBattleState = () => ({ 进行中: false, 战斗ID: '', 轮数: 0, 阶段: '', 参战者: [], 先攻顺序: [], 当前行动者: '', 行动额度: {}, 距离: {}, 掩体: {}, 持续效果: {}, 濒死计数: {}, 最近一次检定: null });
const battleState = z.object({ 进行中: z.boolean().catch(false).prefault(false), 战斗ID: battleId, 轮数: nonNegative(0), 阶段: text(''), 参战者: z.array(stableId).catch([]).prefault([]), 先攻顺序: z.array(stableId).catch([]).prefault([]), 当前行动者: stableId, 行动额度: stateObject, 距离: stateObject, 掩体: stateObject, 持续效果: stateObject, 濒死计数: stateObject, 最近一次检定: checkSummary.nullable().catch(null).prefault(null) }).superRefine((battle, ctx) => {
  if (battle.进行中 && !battle.战斗ID.trim()) ctx.addIssue({ code: 'custom', path: ['战斗ID'], message: '进行中的战斗必须有非空战斗ID' });
  if (battle.进行中 && !battle.阶段.trim()) ctx.addIssue({ code: 'custom', path: ['阶段'], message: '进行中的战斗必须有非空阶段' });
  if (battle.进行中 && battle.参战者.length === 0) ctx.addIssue({ code: 'custom', path: ['参战者'], message: '进行中的战斗必须至少有一名参战者' });
  const hasParticipantData = battle.参战者.length > 0 || battle.先攻顺序.length > 0 || Boolean(battle.当前行动者);
  if (hasParticipantData) {
    const participantSet = new Set(battle.参战者);
    const participantIdsAreValid = battle.参战者.every(id => id) && participantSet.size === battle.参战者.length;
    const initiativeIsValid = participantIdsAreValid && battle.先攻顺序.length === battle.参战者.length && new Set(battle.先攻顺序).size === battle.先攻顺序.length && battle.先攻顺序.every(id => id && participantSet.has(id));
    if (!participantIdsAreValid) ctx.addIssue({ code: 'custom', path: ['参战者'], message: '参战者必须是唯一的非空稳定ID' });
    if (!initiativeIsValid) ctx.addIssue({ code: 'custom', path: ['先攻顺序'], message: '先攻顺序必须是参战者稳定ID的精确排列' });
    if (!battle.当前行动者 || !participantSet.has(battle.当前行动者)) ctx.addIssue({ code: 'custom', path: ['当前行动者'], message: '当前行动者必须是参战者稳定ID' });
  }
}).catch(emptyBattleState()).prefault(emptyBattleState());

export const Schema = z.object({
  世界: z.object({
    当前时间: z.object({ 规范日期: text(), 时段: z.enum(['黎明', '清晨', '上午', '正午', '下午', '傍晚', '夜间', '深夜', '凌晨', '时段未详']).catch('时段未详').prefault('时段未详'), 时间层: z.enum(['主线', '轮回分支', '历史回溯', '试炼幻境']).catch('主线').prefault('主线'), 轮回分支: text('B00') }).passthrough().catch({}).prefault({}),
    当前地点: z.object({ 国家: text(), 地区: text(), 场所: text(), 具体位置: text() }).passthrough().catch({}).prefault({}),
    环境: z.object({ 天气: text(), 光照: text(), 描述: text() }).passthrough().catch({}).prefault({}),
    危机等级: z.enum(['无', '低', '中', '高', '灾难']).catch('无').prefault('无'),
    动向: z.record(z.string(), z.object({ 标题: text('未命名事件'), 阶段: z.enum(['起', '承', '转', '合']).catch('起').prefault('起'), 类型: text(), 地点: text(), 描述: text('') }).passthrough()).catch({}).prefault({}).transform(data => _(data).entries().takeRight(3).fromPairs().value()),
    势力态势: z.record(z.string(), z.object({ 立场: text('中立'), 状态: text(), 描述: text('') }).passthrough()).catch({}).prefault({}),
  }).passthrough().catch({}).prefault({}),
  主角档案: protagonist,
  轮回: z.object({
    世界重启次数: nonNegative(0),
    当前轮回编号: nonNegative(0),
    存档点: z.object({ 有效: z.coerce.boolean().catch(false).prefault(false), 创建时间: text(), 状态快照: z.object({ 世界: stateObject, 主角档案: stateObject, 关系: stateObject, 事件: stateObject, 线索: stateObject, 资产: stateObject }).passthrough().catch({}).prefault({}) }).passthrough().catch({}).prefault({}),
    最近一次重启: z.object({ 死亡事件ID: text('无'), 重启编号: nonNegative(0), 触发时间: text(), 恢复结果: text('无') }).passthrough().catch({}).prefault({}),
    菜月昴死亡记录: z.record(z.string(), deathRecord).catch({}).prefault({}),
    最近一次死亡: z.object({ 死亡ID: text('无'), 直接原因: text('无'), 死亡经过: text('无') }).passthrough().catch({}).prefault({}),
  }).passthrough().catch({}).prefault({}),
  关系: z.object({ 伴侣: z.record(z.string(), partner).catch({}).prefault({}), 契约伙伴: z.record(z.string(), contractedPartner).catch({}).prefault({}), 人物: z.record(z.string(), person).catch({}).prefault({}) }).passthrough().catch({}).prefault({}),
  事件: z.object({ 当前战斗: battleState, 进行中: z.record(z.string(), eventItem).catch({}).prefault({}), 近期记录: limitedRecord(z.object({ 标题: text('未命名事件'), 结果: text(), 规范日期: text(), 参与者: z.array(z.string()).catch([]).prefault([]), 描述: text('') }).passthrough(), 12) }).passthrough().catch({}).prefault({}),
  线索: z.object({ 当前线索: limitedRecord(z.object({ 标题: text('未命名线索'), 状态: text('未解决'), 关联事件: text('无'), 描述: text(''), 下一步: text() }).passthrough(), 30), 未解问题: z.array(z.string()).catch([]).prefault([]) }).passthrough().catch({}).prefault({}),
  资产: z.object({
    货币: z.record(z.string(), z.object({ 数量: nonNegative(0), 持有者: text(), 存放位置: text() }).passthrough()).catch({}).prefault({}),
    物品: z.record(z.string(), z.object({ 名称: text(), 数量: nonNegative(0), 持有者: text(), 存放位置: text(), 描述: text('') }).passthrough()).catch({}).prefault({}).transform(data => _.pickBy(data, item => item.数量 > 0)),
    装备: z.record(z.string(), z.object({ 名称: text(), 持有者: text(), 装备状态: text(), 损耗: percent(0), 当前效果: text('无'), 战斗元数据: combatMetadata.optional() }).passthrough()).catch({}).prefault({}),
    据点与存放: z.record(z.string(), z.object({ 名称: text(), 位置: text(), 控制者: text(), 状态: text() }).passthrough()).catch({}).prefault({}),
  }).passthrough().catch({}).prefault({}),
  规则: z.object({ schema版本: z.literal('re0-state-v1').catch('re0-state-v1').prefault('re0-state-v1'), 初始化完成: z.coerce.boolean().catch(false).prefault(false) }).passthrough().catch({}).prefault({}),
}).passthrough();

$(() => { registerMvuSchema(Schema); });
